// Datenquelle: Pfad bei Bedarf anpassen. Unbekannte Aufträge/Dateifehler verhindern den Start.
string path = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData), "Testumgebung", "fertigungsauftraege.json");
using var data = System.Text.Json.JsonDocument.Parse(System.IO.File.ReadAllText(path));
string order = (Auftrag ?? "").Trim();
if (!data.RootElement.TryGetProperty(order, out var entry))
    return Error("Fertigungsauftrag nicht gefunden: " + order);
string program = entry.GetProperty("Testprogramm").GetString();
if (string.IsNullOrWhiteSpace(program)) return Error("Testprogramm fehlt: " + order);
string article = entry.GetProperty("Artikel").GetString();
SelectTest(program, null, order, "Artikel=" + article);
return Pass(program);
